import Complex128Array = require( '@stdlib/array/complex128' );
import zffti = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const workspace = new Complex128Array( ( 4*8 ) + 34 );

	zffti( 8, workspace, 1, 0 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const workspace = new Complex128Array( ( 4*8 ) + 34 );

	zffti( '8', workspace, 1, 0 ); // $ExpectError
	zffti( true, workspace, 1, 0 ); // $ExpectError
	zffti( false, workspace, 1, 0 ); // $ExpectError
	zffti( null, workspace, 1, 0 ); // $ExpectError
	zffti( void 0, workspace, 1, 0 ); // $ExpectError
	zffti( [], workspace, 1, 0 ); // $ExpectError
	zffti( {}, workspace, 1, 0 ); // $ExpectError
	zffti( ( x: number ): number => x, workspace, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Complex128Array...
{
	zffti( 8, '50', 1, 0 ); // $ExpectError
	zffti( 8, 50, 1, 0 ); // $ExpectError
	zffti( 8, true, 1, 0 ); // $ExpectError
	zffti( 8, false, 1, 0 ); // $ExpectError
	zffti( 8, null, 1, 0 ); // $ExpectError
	zffti( 8, void 0, 1, 0 ); // $ExpectError
	zffti( 8, {}, 1, 0 ); // $ExpectError
	zffti( 8, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const workspace = new Complex128Array( ( 4*8 ) + 34 );

	zffti( 8, workspace, '1', 0 ); // $ExpectError
	zffti( 8, workspace, true, 0 ); // $ExpectError
	zffti( 8, workspace, false, 0 ); // $ExpectError
	zffti( 8, workspace, null, 0 ); // $ExpectError
	zffti( 8, workspace, void 0, 0 ); // $ExpectError
	zffti( 8, workspace, [], 0 ); // $ExpectError
	zffti( 8, workspace, {}, 0 ); // $ExpectError
	zffti( 8, workspace, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const workspace = new Complex128Array( ( 4*8 ) + 34 );

	zffti( 8, workspace, 1, '0' ); // $ExpectError
	zffti( 8, workspace, 1, true ); // $ExpectError
	zffti( 8, workspace, 1, false ); // $ExpectError
	zffti( 8, workspace, 1, null ); // $ExpectError
	zffti( 8, workspace, 1, void 0 ); // $ExpectError
	zffti( 8, workspace, 1, [] ); // $ExpectError
	zffti( 8, workspace, 1, {} ); // $ExpectError
	zffti( 8, workspace, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const workspace = new Complex128Array( ( 4*8 ) + 34 );

	zffti(); // $ExpectError
	zffti( 8 ); // $ExpectError
	zffti( 8, workspace ); // $ExpectError
	zffti( 8, workspace, 1 ); // $ExpectError
	zffti( 8, workspace, 1, 0, 123 ); // $ExpectError
}
